-- « Destinataires » (LecteurDestinatairesRedaction, EcrivainDestinatairesRedaction), lot 10 du plan « RIG v3 100 % fonctionnel »
-- (plan-676a4b19). Identifiants 2 000 6xx, roles 2026DR206xx (instances CX sans code affaire). Les tables, aux definitions des jeux qui les
-- creent aussi (PROC_CORDJRCS.sql pour PARTIE, PROC_EDI_RPJC_REN.sql pour MANDATAIRE : joues avant) ou de RIG_DEV.
-- Ce qui est retenu ou ecarte, et pourquoi : PROC_DEST_REDA.attendu.
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_INSTANCE varchar(2) NULL;
IF OBJECT_ID(N'v2.PARTIE') IS NULL
    CREATE TABLE v2.PARTIE (PRT_ID_PRT int NOT NULL PRIMARY KEY, PRT_ID_INSTN int NOT NULL, PRT_NUM_ORDRE smallint NOT NULL,
        PRT_CIVILITE varchar(7) NOT NULL, PRT_DESIGNATION varchar(512) NULL, PRT_NOM varchar(512) NULL, PRT_SIREN varchar(10) NULL,
        PRT_MODE_PRESENTATION varchar(3) NULL, PRT_QUALIF_PARTIE varchar(5) NOT NULL, PRT_DATE_ACTE datetime NULL);
IF COL_LENGTH('v2.PARTIE', 'PRT_ID_MNDTR_POS') IS NULL ALTER TABLE v2.PARTIE ADD PRT_ID_MNDTR_POS int NULL;
IF COL_LENGTH('v2.PARTIE', 'PRT_ID_MNDTR_PLAI') IS NULL ALTER TABLE v2.PARTIE ADD PRT_ID_MNDTR_PLAI int NULL;
IF COL_LENGTH('v2.PARTIE', 'PRT_EDITION_JUGEMENT') IS NULL ALTER TABLE v2.PARTIE ADD PRT_EDITION_JUGEMENT varchar(5) NULL;
IF COL_LENGTH('v2.PARTIE', 'PRT_MANDATAIRE_EDITION_JUGEMENT') IS NULL ALTER TABLE v2.PARTIE ADD PRT_MANDATAIRE_EDITION_JUGEMENT varchar(5) NULL;
IF COL_LENGTH('v2.PARTIE', 'PRT_MANDATAIRE_PLAI_EDITION_JUGEMENT') IS NULL ALTER TABLE v2.PARTIE ADD PRT_MANDATAIRE_PLAI_EDITION_JUGEMENT varchar(5) NULL;
IF OBJECT_ID(N'v2.MANDATAIRE') IS NULL
    CREATE TABLE v2.MANDATAIRE (MNDTR_ID_MNDTR int NOT NULL PRIMARY KEY, MNDTR_NOM varchar(128) NOT NULL, MNDTR_ACTIF bit NOT NULL,
        MNDTR_NUMERO_CNBF varchar(6) NULL);
IF OBJECT_ID(N'v2.DESTINATAIRE_DIVERS') IS NULL
    CREATE TABLE v2.DESTINATAIRE_DIVERS (DTDIV_ID_DTDIV int NOT NULL PRIMARY KEY, DTDIV_ID_DCJDC int NOT NULL, DTDIV_TYPE varchar(20) NULL,
        DTDIV_DESIGNATION varchar(255) NULL, DTDIV_BLOC_ADRESSE varchar(max) NULL, DTDIV_EDITION_JUGEMENT varchar(5) NULL);
IF OBJECT_ID(N'v2.DOCUMENT_DOSSIER') IS NULL
    CREATE TABLE v2.DOCUMENT_DOSSIER (DCMDS_ID_DCMDS int NOT NULL PRIMARY KEY, DCMDS_CODE_ENTITE varchar(16) NULL, DCMDS_VALEUR_ID_METIER int NULL,
        DCMDS_CODE_MODELE_DOCUMENT varchar(30) NULL, DCMDS_ID_JUG int NULL, DCMDS_ID_GRASS int NULL, DCMDS_DATE_IMPRESSION_MINUTE datetime NULL,
        DCMDS_SUPPLEMENT_GROSSE varchar(100) NOT NULL DEFAULT (''), DCMDS_SUPPLEMENT_COPIE varchar(100) NOT NULL DEFAULT (''),
        DCMDS_SUPPLEMENT_EXPEDI varchar(100) NOT NULL DEFAULT (''));

-- 2000601 (jugement redige, grosses delivrees le 15/03/1990) : deux parties, l'une avec un mandataire postulant et un plaidant (ceux de
-- PROC_MANDATAIRE.sql, 1500101 et 1500102, joue apres : la partie ne porte que leur numero ; un mandataire ajoute ici entrerait dans sa
-- liste) ; un
-- fix-ok: lu dans le code du banc (27/11/2026) -- une ligne attendue est rognee (Program.cs:457-458) : une derniere cellule vide (le supplement
-- d'expeditions) ne se compare jamais ; les deux documents en portent donc un (1 et 0).
-- destinataire divers ; et une partie de qualite « T » (2000605), ni demandeur, ni defendeur, ni intervenant : RIG v2 ne la retient pas
-- (ChargerDestinatairesParDefaut, DestinataireREDA.cs:735-737). 2000602 (redige, sans date de delivrance) : une partie ; « Ajouter » y
-- rattache un destinataire divers (PROC_DEST_REDA.gestes). 2000603 : une partie mais AUCUN document REDA (ecartee).
EXEC sp_executesql N'
